    """Extend marked pixels between two opposing horizontal boundary bars."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda x: sum(row.count(x) for row in g))

    # Find uniform-color runs on the two opposite horizontal borders.
    def runs(row):
        out = []
        i = 0
        while i < w:
            if row[i] == bg:
                i += 1
                continue
            color, start = row[i], i
            while i < w and row[i] == color:
                i += 1
            if i - start >= 2:
                out.append((start, i - 1, color))
        return out

    candidates = []
    for top in runs(g[0]):
        for bot in runs(g[-1]):
            if top[2] == bot[2]:
                candidates.append((top, bot))
    if not candidates:
        return g
    # The pair with greatest separation / combined length is the frame.
    top, bot = max(candidates, key=lambda p: (p[1][2] == p[0][2], (p[0][1]-p[0][0]+1)+(p[1][1]-p[1][0]+1)))
    bar = top[2]
    top_r, bot_r = 0, h - 1

    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    # Non-background/non-frame singleton colors are the movable marks.
    marker_colors = [c for c in counts if c not in (bg, bar)]
    if not marker_colors:
        return g
    mark = min(marker_colors, key=lambda c: counts[c])
    points = [(r, c) for r in range(h) for c in range(w) if g[r][c] == mark]

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and g[r][c] == bg:
            g[r][c] = mark

    # Make each marked cell a 4, then extend its ray toward the bar whose
    # horizontal span contains it. A lone mark spans the whole corridor.
    for r, c in points:
        g[r][c] = 4
        if len(points) == 1:
            for rr in range(top_r + 1, bot_r):
                paint(rr, c)
            continue
        in_top = top[0] <= c <= top[1]
        in_bottom = bot[0] <= c <= bot[1]
        if in_top and not in_bottom:
            for rr in range(top_r + 1, r + 1):
                paint(rr, c)
            base, other = top[0], bot[0]
            offset = c - base
            if offset < min(top[1]-top[0]+1, bot[1]-bot[0]+1) - 1:
                target = other + offset
                for rr in range(top_r, bot_r):
                    paint(rr, target)
        elif in_bottom:
            for rr in range(r, bot_r):
                paint(rr, c)
            base, other = bot[0], top[0]
            offset = c - base
            if offset < min(top[1]-top[0]+1, bot[1]-bot[0]+1) - 1:
                target = other + offset
                for rr in range(top_r, bot_r + 1):
                    paint(rr, target)
        else:
            # Unaligned marks still extend toward the nearer boundary.
            if r <= h - 1 - r:
                for rr in range(r, bot_r):
                    paint(rr, c)
            else:
                for rr in range(top_r + 1, r + 1):
                    paint(rr, c)
